    /**
     * Handles loading a Organization using a UUID
     * @param		UUID uuid 
     * @return		Organization
     */    
    @GetMapping("/load")
    public Organization load( @RequestParam(required=true) UUID uuid ) {    	
    	Organization entity = null;

    	try {  
    		entity = service.getOrganization( new OrganizationFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Organization using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Organization business objects
     * @return		Set<Organization>
     */
    @GetMapping("/")
    public List<Organization> loadAll() {                
    	List<Organization> organizationList = null;
        
    	try {
            // load the Organization
            organizationList = service.getAllOrganization();
            
            if ( organizationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Organizations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Organizations ", exc );
        	return null;
        }

        return organizationList;
                            
    }


